local ServiceProvider = require(script.Parent.Parent.DependencyInjection.ServiceProvider)

local InternalHost = {}
InternalHost.__index = InternalHost

function InternalHost.new(services: IServiceProvider): IHost
	local self = setmetatable({}, InternalHost)
	self.Services = services
	return self
end

function InternalHost:Start()
	print("启动唐僧后台服务")
	local hostBootstrap = self.Services:GetService("IHostServicesBootstrap")
	hostBootstrap:Start()
	print("启动唐僧后台服务完成")
end

function InternalHost:Stop()
	self.Services:GetService("IHostServicesBootstrap"):Stop()
end

return InternalHost
